=4&&!NQ(RT[rd]).includes(q.slice(0,240)))cv4('E-OOR',j.seat,l,'the sentence is not found verbatim in ['+rd+'] (\"the verbatim sentence in which the ground was granted\")');","  if(counted&&!/^(CR4|DR4)$/.test(rd))cv4('E-OOR',j.seat,l,'COUNTED ends a line from ['+rd+']; only a close-round ([CR4] or [DR4]) concession enters the counts (\"Ground granted in [CR1], [DR1], [CR2] or [DR2] ... does not enter those counts\")');}"," for(const sd of ['DEFENDER','CHALLENGER']){const ml=ls.find(l=>new RegExp('^'+sd+' CHAIN MARK\\\\s*:').test(l));if(!ml)continue;const mk=(ml.match(/CHAIN MARK\\s*:\\s*(FOOTED|STRAINED|SLACK)\\b/)||[])[1];if(mk!=='FOOTED')continue;","  /* only the link the judge's own mark names is read (the rule speaks of the load-bearing link; the mark names it: \"one clause naming the load-bearing","     link that decides the mark\"); a mark that names no link by number, or \"keystone\" for the last link, is not checked */","  const bl=blocksOf(sd==='DEFENDER'?R&&R.CR3:R&&R.DR3);if(!bl.length)continue;const clause=ml.replace(/^[A-Z ]+CHAIN MARK\\s*:\\s*[A-Z]+\\s*/,'');","  const nm=clause.match(/\\b(?:[DC]|LINK\\s*)(\\d+)\\b/i);const ln=nm?+nm[1]:(/\\bkeystone\\b/i.test(clause)?Math.max(...bl.map(b=>b.link)):null);if(ln===null)continue;","  const named=bl.filter(b=>b.link===ln);if(!named.length)continue;const best=Math.max(...named.map(b=>layersOf(b.t)));","  if(best<2)cv4('E-CHAIN',j.seat,ml,sd+' CHAIN MARK is FOOTED, but the link its own clause names (LINK '+ln+') exhibits '+best+' prior layer(s) in its link round; \"a link floats only when the block that states it exhibits fewer than two prior layers\" (STRAINED)');}}","/* pkgEB7 (rulings item 13): E-B7, each B7 hit (a premise this judge counts UNEXHIBITED on a verse whose ANSWER CHECK lines by the same judge, on","   that side's answers, all read MEETS) put to DeepSeek: same ground or different ground. Side-neutral: CONCEDED LINKS reads the defender's answers","   ([CR] rounds), CHALLENGER CONCEDED LINKS the challenger's ([DR] rounds), as selfLines421 does. */","{const __acG=a=>{const r=__ri11(a);if(r)return /^(MEETS|MISSES|FAILS)$/.test(r.f.grade)?r.f.grade:null;return __acG0(a);}; /* pkgRP11 */"," const __acG0=a=>{const m=String(a).match(AC);if(m)return m[5];const g=[...String(a).matchAll(/--\\s*(MEETS|MISSES|FAILS)\\b/g)];return g.length?g[g.length-1][1]:null;};"," const __seen=new Set();let __si=0;"," for(const j of judges){const ls=linesOf(j.t);const acs=ls.filter(l=>/^ANSWER CHECK:/.test(l));","  for(const l of ls){const h=l.match(/^(CHALLENGER CONCEDED LINKS|CONCEDED LINKS)\\s*:(.*)$/i);if(!h)continue;const sd=/^CHALLENGER/i.test(h[1])?'C':'D';const rl=sd==='D'?'C':'D';","   for(const seg of h[2].split(/(?=\\bpremise\\s+\\d+)/i)){const pm=seg.match(/^premise\\s+(\\d+)/i);if(!pm||!/\\bUNEXHIBITED\\b/i.test(seg))continue;const n=+pm[1];","    const hit=[],own=[];for(const r of refsOf(seg)){const o=acs.filter(a=>{const __r=__ri11(a);const m=__r?(__r.f.rounds.length?[a,__r.f.verse,__r.f.rounds[0][0]]:null):a.match(/^ANSWER CHECK:\\s*(.+?)\\s*--\\s*\\[\\s*([CD])R/); /* pkgRP11 */return m&&m[2]===rl&&refsOf(m[1]).has(r);});","     if(o.length&&o.every(a=>__acG(a)==='MEETS')){hit.push(r);for(const a of o)if(!own.includes(a))own.push(a);}}","    if(!hit.length)continue;const key=j.seat+'|'+sd+'|'+n;if(__seen.has(key))continue;__seen.add(key);__si++;const id='S'+__si+'.1';","    const V=hit.map(r=>r.replace(/\\b[a-z]/g,c=>c.toUpperCase())).join(', ');const e=entry(sd,n)||'';const sideW=sd==='D'?'defender':'challenger';","    const means=own.map(a=>{const m=String(a).match(AC);return m?m[3]:'';}).filter(Boolean);","    items.push({ids:[{id,rule:'E-B7',seat:j.seat,grade:'DIFFERENT GROUND',item:'SELF-CONTRADICTION '+sideW+' premise '+n+' on '+V,flagged_line:l.slice(0,1500),response_line:own.join('\\n').slice(0,700),","      b7:{side:sd==='D'?'DEFENDER':'CHALLENGER',n,refs:hit,verses:V,round:rl+'R',entry:e.slice(0,1500),seg:seg.trim().slice(0,600),means:means.map(x=>x.slice(0,600)),ac:own.map(a=>a.slice(0,900))}}],","     text:'ITEM S'+__si+' (E-B7, a premise this judge counts UNEXHIBITED on '+V+', where its own ANSWER CHECK lines on the '+sideW+'\\'s answers read MEETS):\\nTHE PREMISE (number '+n+', listed against the '+sideW+'): '+(e?cut(e,1200):'(the list entry was not found)')","      +'\\nTHIS JUDGE\\'S COUNT ('+id+', '+j.seat+'): '+cut(seg.trim(),600)+'\\nTHIS JUDGE\\'S ANSWER CHECK LINES ON '+V+' (each MEETS):\\n'+own.map(a=>'- '+cut(a,900)).join('\\n')});}}}}","if(!items.length&&!eakHas2024())return [{json:{je_skip:true,why:'no judge decision line and no synthesis claim was read',items:[],code_rows}}]; /* pkgEAK2: an alternate K-W/K-S3 cure row still gets its DeepSeek call */","const SYS='You are the enforcer of a debate panel. You check the judges\\' written grades against the debate words quoted to you. You bring nothing from outside the record: no doctrine, no training knowledge, no reading of your own. You do not judge the debate.';","const RULES='RULE E-ANS (an answer to a pressed verse). The answer is every line the answering side wrote under the pressed verse, up to the next pressed verse, its layers included; when THE ANSWER IN FULL is given, grade it, not a shorter quotation of it in a judge line. An opening grant (\"I grant it\") followed by a layer that shows how the verse fits the answering side\\'s case MEETS. Decide FIRST what the right grade is: MEETS only when the answer shows, in its own words, how the verse fits the answering side\\'s case, or why the stated meaning does not follow from what the verse says. MISSES when the answer rests on an absence (it says only that the verse, or the other side, names no, states no, does not name, gives no, or is silent on something) without a fit of its own, or when it does not address the stated meaning. An answer that quotes the verse\\'s own words against the specific claim of the stated meaning (for example, the verse\\'s own stated grounds set against a claim that there were no grounds) shows why the meaning does not follow: it MEETS, even when it closes with a bare assertion such as \"It fits the link\". Then for each judge\\'s grade: AGREE when it matches the right grade, DISAGREE when it does not.\\n'"," +'RULE E-VOID (a listed premise ruled VOID). A premise is VOID only when its charge says the opponent\\'s quoted words state something they do not state (a negation, a universal, or another claim beyond the quote). The charge is the premise\\'s own words before its quote (for example \"The inference that ...\"), read against the words of that quote. Set aside only a clause saying what the premise props (\"which props ...\") or a sentence naming the objection it serves (\"The objection it props is ...\"); those are not part of the charge. AGREE with the VOID ruling when the charge goes beyond its quote; DISAGREE when it does not.\\n'"," +'RULE E-COL (a collision line: FORCED, or LINK BROKEN). THE WITNESS LEDGER (pkgWLDDS), when an item gives it, is the system\\'s record of the rounds, the same one the judges were shown: a witness NAMED IN AN ANSWER was answered by name in the round shown, so a line that rests on that witness being unanswered or left unanswered is wrong on that ground (DISAGREE, and say so), though whether that answer meets the meaning pressed is still read from its quoted words; a witness NOT NAMED was named in no later round of the answering side; NAMED ONLY IN OTHER TEXT decides neither. A LINK BROKEN line given with THE SAME JUDGE\\'S FORCED LINE on that collision is read with it as one ruling: the words that FORCED line quotes (its MEANS and its ANSWER) are the quotes of the break, so do not DISAGREE because the LINK BROKEN line itself quotes no answer words; judge the break by those quoted words, under the rest of this rule (pkgECP, either side alike). A link is broken only when the answer\\'s own quoted words cannot agree with the meaning pressed, as the line quotes them; it is not broken because no verse states it, or because of an absence, and it is not broken by a rival reading: an answer that reads a contested word another way, with its own layers quoted in its round, can agree with the meaning on its own reading (pkgECF, W3 2534; either side alike). A link is also broken when a proven press against it was left unanswered (Commitment 5) and the line quotes the pressing sentence and names its round (ruling 392); that is not a break by absence. Its cure line is PRESSED: D<n> vs C<m> | [<round>] | <the pressing words in quotation marks>, the round [DR1] or [DR2] against the defender, [CR1], [CR2] or [CR3] against the challenger, its words standing word for word in that round; it does not cure when a later round of the side that holds the link names every pressed witness the line rests on. A FORCED line breaks a link by meaning only when its MEANS quotes the pressing side\\'s own sentence in the round it names; a verse re-quoted as the MEANS is not that, and when the item carries a CODE CHECK saying so, DISAGREE (pkgEFG, either side alike). When the item says the FAILS words are found exactly in the round of the answer, those words are the answering side\\'s own and are read as part of its answer. AGREE when the quoted words show the answer cannot agree with the meaning; DISAGREE when they do carry a meaning the link can agree with, or the line rests on an absence or on a demand for a stating verse. A line\\'s layers after GROUND ([L1], [L2], [L3]; Commitment 13) are counted in code, not by you: read them as the judge\\'s grounds.\\n'"," +'RULE E-SYN (a sentence of the synthesis saying a side withdrew, conceded, granted, dropped or narrowed something). AGREE when that side\\'s own sentences given you give up that same thing at the same scope; DISAGREE when they do not, or give up less (for example, \\\"no row I cite\\\" is not \\\"no biblical text\\\").\\n'"," +'RULE E-HOLD (a collision line graded STANDS or UNDERDETERMINED). THE WITNESS LEDGER (pkgWLDDS), when an item gives it, is the system\\'s record of the rounds, the same one the judges were shown: a witness NAMED IN AN ANSWER was answered by name in the round shown, so a line that rests on that witness being unanswered or left unanswered is wrong on that ground (DISAGREE, and say so), though whether that answer meets the meaning pressed is still read from its quoted words; a witness NOT NAMED was named in no later round of the answering side; NAMED ONLY IN OTHER TEXT decides neither. STANDS is right only when the answering side\\'s own words, as quoted to you in the line or in this judge\\'s ANSWER CHECK lines, carry a meaning the link can agree with for the meaning pressed. UNDERDETERMINED is right only when the quoted words show that both readings agree with the pressed verse and neither side\\'s words show that the other cannot. BROKEN when the answer\\'s quoted words cannot agree with the meaning pressed, or the answer is only a bare grant or an absence with no fit of its own. An answer is every line the answering side wrote under the pressed verse, its layers included (THE ANSWER IN FULL, when given under an ANSWER CHECK line); an opening grant followed by a layer that shows the fit is not a bare grant. A ground that rests on an absence (no verse states it, the text does not narrate it), or on the judge\\'s own reading rather than the debate\\'s words, is not a ground. Each ANSWER CHECK line given you is labelled with whose answer it grades: a MISSES or FAILS on the challenger\\'s answer counts against the challenger\\'s link, never against the defender\\'s, and the reverse. A press labelled UNPROVEN carries no answering burden, so a MISSES on it breaks nothing. For a link-state line (\\\"D5: STANDS\\\"), the quoted answers are that side\\'s ANSWER CHECK lines given you: STANDS is right unless one of them, on a press against this link, is MISSES or FAILS. AGREE when the judge\\'s grade is right; DISAGREE when it is not. When the right grade is BROKEN and the answering side answered the pressed verse (an ANSWER CHECK line given you quotes its answer, graded MISSES or FAILS), the break is one of meaning and counts only as a FORCED line for the pair (ruling 421; the gate checks it, K-G4): your reason says so and names it, FORCED: <Dn vs Cm> -- MEANS [<round>]: \"<the pressing sentence>\" -- ANSWER [<round>]: \"<the answer\\'s words>\" -- FAILS: \"<the words that cannot agree>\". Never ask for a plain LINK BROKEN line on a witness the side answered (pkgEHF).\\n'"," +'RULE E-KEY (the keystone line). The keystone grade must follow from this judge\\'s own collision lines on that link, given to you: STANDS only when none of them grades the link BROKEN or FORCED and the link was not withdrawn; BROKEN when one of them does. Its ground, where it gives one, must rest on the debate\\'s words, not on the judge\\'s own statement of doctrine. A ground that restates the defender\\'s own words for the keystone, given to you under THE DEFENDER\\'S OWN WORDS FOR THE KEYSTONE (its opening statement, or its premise line for that link), rests on the debate\\'s words: the defender\\'s thesis restated is not the judge\\'s own doctrine (pkgEKD). AGREE when the keystone grade follows and its ground rests on the debate\\'s words; DISAGREE when it does not.\\n'"," +'RULE E-PREM (a listed premise, and how each judge ruled it). The judges\\' own rules, quoted: \"A LINK ROUND answer that neither exhibits the premise\\'s layer footing nor concedes counts as CONCEDED.\" \"SELF-SUPPORTED = every listed defender claim is carried by its layer stack -- each [L4] exhibits the [L1]/[L2]/[L3] footing it rests on (at least two prior layers exhibited; a shown chain counts equally).\" For a charge in the form ASSUMES: ... -- ROWS GIVE: ...: \"the premise is UNEXHIBITED when no quoted row gives the fact it assumes, and it stands when a row the side quoted gives that fact.\" \"UNEXHIBITED also fires ... when a narrowed link keeps words that still assert what its own side gave up.\" And: \"What a link INFERS from its rows is its [L4]: it is graded by the two-layer rule and by the meaning of the verses pressed against it, and never as a missing row (DG-61); an inferred act, such as a begetting or a knowing, is never an ASSUMES.\" A premise \"charged in terms stronger than its quote, is VOID\" (RULE E-VOID). For premise N only, decide FIRST the right ruling: COUNTED (UNEXHIBITED or CONCEDED), SPARED, or VOID. The judges\\' form reads \"Itemize the counted links\": a premise the judge\\'s line does not name is that judge\\'s SPARED ruling. AGREE when the judge\\'s ruling on premise N (named, or spared by silence) is the right one; DISAGREE when it is not; NO ANSWER only when the judge\\'s line is not in its form. A NARROWED premise (the side drops a claim and keeps the link on a narrower footing, with its [L1] and [L2] or [L3] exhibited) is SPARED: dropping a claim is not conceding the premise, and the dropped claim alone never makes the premise COUNTED. It is UNEXHIBITED only when the kept words still assert the very claim the side dropped; say so by quoting both the dropped claim and the kept words that still assert it.\\n'"," +'RULE E-PREM, A RECOUNTED LINE (pkgERC). When a judge\\'s line says the engine recounted it, that judge\\'s ruling on premise N is the one its STORED COUNTED PREMISES give: COUNTED when N is listed, SPARED when it is not; the line\\'s silence is not a SPARED ruling. Judge that ruling as any other, from the block, the judge\\'s line before the recount and its own collision lines shown. When the ruling is COUNTED and none of those lines gives a ground for premise N, say \"counted with no stated ground\" in your sentence.\\n'"," +'RULE E-PREM, THE COUNTED KIND (pkgEPS). UNEXHIBITED means a missing layer: the answering block does not exhibit a layer its footing needs. When your RIGHT is COUNTED, begin your sentence with its kind in brackets: (UNEXHIBITED: lacks [L1]), naming each layer ([L1], [L2] or [L3]) the block does not exhibit; or (CONCEDED), quoting the side\\'s own words that give the premise up. A ground of fit or meaning (the answer does not meet a pressed verse, or reads it another way) is not a missing layer: it is graded at the collision (RULE E-COL, RULE E-HOLD), not counted here, so it is not COUNTED.\\n'"," +'RULE E-RES (a judge\\'s RESULT line). Its arithmetic is checked in code. Read only its reason sentence: by the judges\\' Commitment 1 (the record is the only evidence) and Commitment 3 (ruling 405), a reason that rests on an absence (no verse states it, the text does not narrate it) or on the judge\\'s own doctrine rather than the debate\\'s words is not a reason. FOLLOWS when the reason rests on the debate\\'s words; DOES NOT FOLLOW when it does not, quoting the words that show it. AGREE when FOLLOWS; DISAGREE when DOES NOT FOLLOW.\\n'"," +'RULE E-B7 (a premise counted UNEXHIBITED while the same judge grades MEETS an answer on the same verse; ruling 421, one judge may not hold both on one ground). UNEXHIBITED says the side did not show the fact the premise assumes. MEETS says the side\\'s answer showed how the verse fits its case against the press. Decide FIRST the right reading: SAME GROUND when a MEETS line\\'s press (its MEANS) and its answer concern the very fact the premise is counted as missing, so the two rulings cannot both stand; DIFFERENT GROUND when the press concerns another fact than the one the premise assumes (for example, the press is about who is addressed, while the premise is about whose house she is of). Read only the premise entry, the judge\\'s count and the ANSWER CHECK lines given you. AGREE when DIFFERENT GROUND; DISAGREE when SAME GROUND, quoting the premise words and the MEANS words that are the same fact.\\n'"," +'NO ANSWER, for every rule: the judge\\'s line lacks its grade or its ground, or is not in its form. It reports a violation by the judge; it is never your own uncertainty, and you choose AGREE or DISAGREE whenever the